#include <bits/stdc++.h>
using namespace std;
int main() {
    const int BITS = 16;
    int n;
    scanf("%d", &n);
    vector<int> a(n), f(1 << BITS, 0);
    for (int i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        f[a[i]]++;
    }
    for (int b = 0; b < BITS; b++)
        for (int mask = 0; mask < (1 << BITS); mask++)
            if (mask & (1 << b)) f[mask] += f[mask ^ (1 << b)];
    for (int i = 0; i < n; i++) printf(i ? " %d" : "%d", f[a[i]]);
    printf("\n");
    return 0;
}
